using System;
using Framework.Grid;
using Framework.Pathfinding;
using Game.AI.Core;
using Game.AI.Parameters;
using Game.Map;
using UnityEngine;

namespace Game.AI.Spatial
{
    /// <summary>
    /// 敵AIの縄張りに関する距離管理と行動評価を行う。
    /// </summary>
    /// <remarks>
    /// 縄張りは移動制限ではなく、
    /// 行動選択に影響する評価情報として扱う。
    /// 距離マップは必要になった時点で再計算する。
    /// </remarks>
    public sealed class MazeEnemyTerritory : IDisposable
    {
        /// <summary>
        /// 縄張り意識による最大評価ペナルティ。
        /// 評価倍率が0にならないようにする。
        /// </summary>
        public const float MaximumPenalty = 0.9f;

        /// <summary>
        /// 評価対象となる敵AIコンテキスト。
        /// </summary>
        private readonly MazeEnemyContext context;

        /// <summary>
        /// 初期化時に取得したステージのグリッド。
        /// </summary>
        private readonly GridMap<MazeCell> map;

        /// <summary>
        /// 縄張り中心からの最短移動距離マップ。
        /// </summary>
        private readonly GridDistanceMap<MazeCell> distanceMap;

        /// <summary>
        /// 最後に距離計算を試みた縄張り中心。
        /// </summary>
        private Vector2Int cachedCenter;

        /// <summary>
        /// 距離マップの再計算が必要であるか。
        /// </summary>
        private bool isDirty = true;

        /// <summary>
        /// 破棄済みであるか。
        /// </summary>
        private bool isDisposed;

        /// <summary>
        /// 距離マップの再計算を実行した回数。
        /// </summary>
        private long recalculationCount;

        /// <summary>
        /// 評価対象となる敵AIコンテキスト。
        /// </summary>
        public MazeEnemyContext Context => context;

        /// <summary>
        /// 現在の縄張り中心座標。
        /// </summary>
        public Vector2Int Center =>
            context.TerritoryCenter;

        /// <summary>
        /// 現在の縄張り半径。
        /// 単位はセル数。
        /// 無効な状態では0を返す。
        /// </summary>
        public float Radius =>
            IsValid
                ? context.GetParameterValue(
                    MazeEnemyParameter.TerritoryRadius)
                : 0f;

        /// <summary>
        /// 現在の縄張り意識。
        /// 値の範囲は0から1。
        /// 無効な状態では0を返す。
        /// </summary>
        public float Territoriality =>
            IsValid
                ? context.GetParameterValue(
                    MazeEnemyParameter.Territoriality)
                : 0f;

        /// <summary>
        /// 縄張り評価を利用可能な状態であるか。
        /// </summary>
        public bool IsValid =>
            !isDisposed && context.IsValid;

        /// <summary>
        /// 距離マップの再計算が必要であるか。
        /// </summary>
        public bool IsDirty =>
            IsValid &&
            (isDirty || cachedCenter != Center);

        /// <summary>
        /// 破棄済みであるか。
        /// </summary>
        public bool IsDisposed => isDisposed;

        /// <summary>
        /// 距離マップの再計算を実行した累計回数。
        /// </summary>
        public long RecalculationCount =>
            recalculationCount;

        /// <summary>
        /// 縄張り評価システムを生成する。
        /// </summary>
        /// <param name="context">敵AIコンテキスト</param>
        /// <exception cref="ArgumentNullException">
        /// コンテキストが指定されていない場合。
        /// </exception>
        /// <exception cref="ArgumentException">
        /// コンテキストが無効な場合。
        /// </exception>
        public MazeEnemyTerritory(
            MazeEnemyContext context)
        {
            if (context == null)
            {
                throw new ArgumentNullException(
                    nameof(context));
            }

            if (!context.IsValid)
            {
                throw new ArgumentException(
                    "無効な敵AIコンテキストです。",
                    nameof(context));
            }

            this.context = context;

            map = context.Map;

            distanceMap = new GridDistanceMap<MazeCell>(
                map,
                context.IsWalkable);

            // 通行可能性の変更を検知する。
            map.CellChanged += HandleCellChanged;
        }

        /// <summary>
        /// 必要に応じて縄張りの距離マップを更新する。
        /// </summary>
        /// <returns>
        /// 有効な距離マップを利用できる場合はtrue
        /// </returns>
        /// <remarks>
        /// 縄張り中心または通行可能性が変更された場合のみ
        /// 距離マップを再計算する。
        /// </remarks>
        public bool Refresh()
        {
            if (!IsValid)
            {
                return false;
            }

            if (!IsDirty)
            {
                return distanceMap.IsCalculated;
            }

            Vector2Int center = Center;

            // 実際に距離計算を試みた回数を記録する。
            if (recalculationCount < long.MaxValue)
            {
                recalculationCount++;
            }

            // 例外が発生した場合は無効状態を維持する。
            isDirty = true;

            bool calculated =
                distanceMap.Calculate(center);

            cachedCenter = center;

            // 起点が通行不可能な場合も計算結果を記録する。
            // 次の通行条件変更まで無駄な再計算を行わない。
            isDirty = false;

            return calculated;
        }

        /// <summary>
        /// 距離マップを無効化する。
        /// </summary>
        /// <remarks>
        /// この時点では再計算を実行しない。
        /// 次回の評価要求時に再計算する。
        /// </remarks>
        public void Invalidate()
        {
            if (!IsValid)
            {
                return;
            }

            isDirty = true;
        }

        /// <summary>
        /// 縄張り中心から指定セルまでの距離を取得する。
        /// </summary>
        /// <param name="position">対象のセル座標</param>
        /// <returns>
        /// 最短移動距離。
        /// 到達不可能または無効な場合は-1
        /// </returns>
        public int GetDistance(Vector2Int position)
        {
            if (!IsValid || !map.IsInside(position))
            {
                return -1;
            }

            if (!Refresh())
            {
                return -1;
            }

            return distanceMap.GetDistance(position);
        }

        /// <summary>
        /// 指定セルが縄張り内に存在するか確認する。
        /// </summary>
        /// <param name="position">判定対象のセル座標</param>
        /// <returns>縄張り内に存在する場合はtrue</returns>
        public bool IsInsideTerritory(
            Vector2Int position)
        {
            int distance = GetDistance(position);

            return distance >= 0 &&
                distance <= Radius;
        }

        /// <summary>
        /// 指定セルに対する縄張り評価を行う。
        /// </summary>
        /// <param name="position">評価対象のセル座標</param>
        /// <param name="evaluation">縄張り評価結果</param>
        /// <returns>
        /// 有効な評価結果を取得できた場合はtrue
        /// </returns>
        /// <remarks>
        /// 到達不可能なセルは評価対象外とする。
        /// パラメーターは評価時点の現在値を使用する。
        /// </remarks>
        public bool TryEvaluate(
            Vector2Int position,
            out MazeEnemyTerritoryEvaluation evaluation)
        {
            evaluation = default;

            int distance = GetDistance(position);

            if (distance < 0)
            {
                return false;
            }

            float radius = Radius;

            float territoriality = Territoriality;

            // 縄張り半径を超過した距離を計算する。
            float outsideDistance =
                Mathf.Max(0f, distance - radius);

            // 半径が0の場合にも対応する。
            float normalizationDistance =
                Mathf.Max(1f, radius);

            // 逸脱距離を0から1へ正規化する。
            float outsideRatio = Mathf.Clamp01(
                outsideDistance / normalizationDistance);

            // 縄張り意識に応じて移動先評価を低下させる。
            float preferenceMultiplier =
                1f - MaximumPenalty *
                territoriality * outsideRatio;

            // 縄張り意識と逸脱度から帰還欲求を求める。
            float returnScore =
                territoriality * outsideRatio;

            evaluation =
                new MazeEnemyTerritoryEvaluation(
                    position,
                    Center,
                    distance,
                    radius,
                    territoriality,
                    outsideDistance,
                    outsideRatio,
                    preferenceMultiplier,
                    returnScore);

            return true;
        }

        /// <summary>
        /// 自身の現在位置に対する縄張り評価を行う。
        /// </summary>
        /// <param name="evaluation">縄張り評価結果</param>
        /// <returns>
        /// 有効な評価結果を取得できた場合はtrue
        /// </returns>
        /// <remarks>
        /// 移動途中の場合は最後に到達したセルを評価する。
        /// </remarks>
        public bool TryEvaluateCurrentPosition(
            out MazeEnemyTerritoryEvaluation evaluation)
        {
            evaluation = default;

            if (!IsValid)
            {
                return false;
            }

            return TryEvaluate(
                context.CurrentCell,
                out evaluation);
        }

        /// <summary>
        /// 指定セルに対する移動先評価倍率を取得する。
        /// </summary>
        /// <param name="position">評価対象のセル座標</param>
        /// <returns>
        /// 移動先評価倍率。
        /// 評価できない場合は0
        /// </returns>
        public float GetPreferenceMultiplier(
            Vector2Int position)
        {
            if (!TryEvaluate(position, out var evaluation))
            {
                return 0f;
            }

            return evaluation.PreferenceMultiplier;
        }

        /// <summary>
        /// 指定セルから縄張りへ帰還する欲求を取得する。
        /// </summary>
        /// <param name="position">評価対象のセル座標</param>
        /// <returns>
        /// 帰還欲求。
        /// 評価できない場合は0
        /// </returns>
        public float GetReturnScore(
            Vector2Int position)
        {
            if (!TryEvaluate(position, out var evaluation))
            {
                return 0f;
            }

            return evaluation.ReturnScore;
        }

        /// <summary>
        /// 自身の現在位置から縄張りへ帰還する欲求を取得する。
        /// </summary>
        /// <returns>
        /// 帰還欲求。
        /// 評価できない場合は0
        /// </returns>
        public float GetReturnScore()
        {
            if (!TryEvaluateCurrentPosition(
                out var evaluation))
            {
                return 0f;
            }

            return evaluation.ReturnScore;
        }

        /// <summary>
        /// グリッドのセル変更を処理する。
        /// </summary>
        /// <param name="position">変更されたセル座標</param>
        /// <param name="previousCell">変更前のセル情報</param>
        /// <param name="newCell">変更後のセル情報</param>
        private void HandleCellChanged(
            Vector2Int position,
            MazeCell previousCell,
            MazeCell newCell)
        {
            if (isDisposed)
            {
                return;
            }

            // 通行可能性が変化していない場合は無視する。
            // 宝石やアイテムの取得では再計算しない。
            if (previousCell.IsWalkable ==
                newCell.IsWalkable)
            {
                return;
            }

            isDirty = true;
        }

        /// <summary>
        /// 縄張り評価システムを破棄する。
        /// </summary>
        /// <remarks>
        /// コンテキストやパラメーターの破棄は行わない。
        /// 複数回呼び出しても安全に処理する。
        /// </remarks>
        public void Dispose()
        {
            if (isDisposed)
            {
                return;
            }

            isDisposed = true;

            // グリッドの変更通知を解除する。
            map.CellChanged -= HandleCellChanged;

            distanceMap.Clear();

            isDirty = false;
        }
    }
}
